import{z as o,x as A,o as E,c as n,q as s,j as l,D as e,d as i,s as B,S as r}from"./chunks/framework.C8m1ZpeB.js";const C=JSON.parse('{"title":"窗口缩放与时间戳","description":"","frontmatter":{"title":"窗口缩放与时间戳","date":"2026-09-08T00:00:00.000Z","section":"cs"},"headers":[],"relativePath":"cs/window-scale-timestamps.md","filePath":"cs/window-scale-timestamps.md","lastUpdated":1791063341000}'),p={name:"cs/window-scale-timestamps.md"};function d(T,a,c,S,m,h){const t=A("Mermaid");return E(),n("div",null,[a[2]||(a[2]=s('<h1 id="窗口缩放与时间戳" tabindex="-1">窗口缩放与时间戳 <a class="header-anchor" href="#窗口缩放与时间戳" aria-label="Permalink to &quot;窗口缩放与时间戳&quot;">​</a></h1><div class="epigraph"><p>缩放把 16 位窗口左移，才能表示 BDP；时间戳做 PAWS 与更准的 RTT，让大窗口上的序号回绕可区分。</p><footer>—— 据 RFC 7323 TCP Window Scale 与 Timestamps 整理</footer></div><p><a href="/cs/bandwidth-delay-product">上一课</a> 算出窗口必须超过 64 KiB。主干窗口课只点名缩放。缺口是 <strong>RFC 7323 选项</strong>：scale 因子、TS 选项、PAWS。本课不把 MSS 钳制写完。</p><h2 id="问题" tabindex="-1">问题 <a class="header-anchor" href="#问题" aria-label="Permalink to &quot;问题&quot;">​</a></h2><p>窗口字段 16 位，最大 65535 字节。scale \\(S\\) 使有效窗口 \\(=W\\ll S\\)，握手时交换。中间若剥选项，一边大窗口一边小，吞吐塌——像双工错配。时间戳：每段带 TS，回 ACK 带回 echo，RTT 样本更密；PAWS 用 TS 丢旧包，防 1 Gb/s 上 32 位序号回绕。卫星与 10G 都需要。</p><p><span class="marginnote">数字实例：1 Gb/s 链路往返 32 ms，BDP = 4 MB；窗口字段只装得下 65535，取 scale=6 后有效窗口 65535×64 ≈ 4.2 MB，刚好填满管道——没有缩放这条链路永远跑不满。</span></p><p>不要把时间戳当成 NTP 同步：它是连接内单调时钟，不必与世界时对齐。</p><p><span class="marginnote">RFC 7323 取代 1323。中间盒对选项不友好是运营现实。本课不把 TSopt 格式逐比特背。</span></p><h3 id="选项在握手钉死" tabindex="-1">选项在握手钉死 <a class="header-anchor" href="#选项在握手钉死" aria-label="Permalink to &quot;选项在握手钉死&quot;">​</a></h3><p>缩放才能表示 BDP。时间戳服务 RTT 与 PAWS，不是 NTP。中间剥选项造成假流控。</p><p><span class="marginnote">术语翻译：PAWS 就是「防序号回绕」的门禁——用时间戳当第二重身份证，凡是带着比本连接已见过的更旧时间戳的段，一律当作上一圈序号的残影拒收，不动连接状态。</span></p><h2 id="方法" tabindex="-1">方法 <a class="header-anchor" href="#方法" aria-label="Permalink to &quot;方法&quot;">​</a></h2><p>画三次握手带上 scale 与 TS。对照：无缩放的长肥管道永远 AIMD 不满。安全：时间戳可作隐蔽信道或指纹，政策可关，代价是 PAWS 与 RTT。</p>',13)),(E(),l(r,null,{default:e(()=>[B(t,{id:"mermaid-37",class:"mermaid",graph:"flowchart%20TD%0A%20%20HS%5B%22%E6%8F%A1%E6%89%8B%E4%BA%A4%E6%8D%A2%20scale%20%E4%B8%8E%20TS%22%5D%20--%3E%20W%5B%22%E6%9C%89%E6%95%88%E7%AA%97%E5%8F%A3%20W%20%E5%B7%A6%E7%A7%BB%22%5D%0A%20%20TS%5B%22%E6%97%B6%E9%97%B4%E6%88%B3%E5%9B%9E%E6%98%BE%22%5D%20--%3E%20RTT%5B%22RTT%20%E6%A0%B7%E6%9C%AC%22%5D%0A%20%20TS%20--%3E%20PAWS%5B%22%E9%98%B2%E5%BA%8F%E5%8F%B7%E5%9B%9E%E7%BB%95%22%5D%0A"})]),fallback:e(()=>[...a[0]||(a[0]=[i(" Loading... ",-1)])]),_:1})),a[3]||(a[3]=s('<h2 id="机制" tabindex="-1">机制 <a class="header-anchor" href="#机制" aria-label="Permalink to &quot;机制&quot;">​</a></h2><p>快恢复的 FlightSize 用缩放后窗口。SYN cookies 后课可能丢掉某些选项，大窗口失败。QUIC 后课自带 32 位以上流控，不借 TCP 选项。ECN 与 TS 正交。</p><p>测量：抓包看 wscale 因子；iperf 差常是这边没协商上。</p><h2 id="边界" tabindex="-1">边界 <a class="header-anchor" href="#边界" aria-label="Permalink to &quot;边界&quot;">​</a></h2><p>本课不引入 TCP AO 认证选项全文。MSS 与钳制是下一课。后课默认：长肥管道必须缩放；TS 服务 RTT 与 PAWS。</p><p>盲目关选项「为了安全」会把卫星用户窗死。</p><p><span class="marginnote">常见误区：以为 TS 选项要求两端时钟同步——它在连接内只用单调递增的「自家滴答」，起点随意、与世界时间无关；比较只在本连接内进行，不需要 NTP。</span></p>',7)),(E(),l(r,null,{default:e(()=>[B(t,{id:"mermaid-59",class:"mermaid",graph:"flowchart%20TD%0A%20%20P%5B%22%E6%94%B6%E5%88%B0%E6%95%B0%E6%8D%AE%E6%AE%B5%22%5D%20--%3E%20T%7B%22%E6%AE%B5%20TSval%20%E6%AF%94%E5%B7%B2%E8%A7%81%E8%BF%87%E7%9A%84%E6%9C%80%E6%96%B0%E5%80%BC%E6%96%B0%EF%BC%9F%22%7D%0A%20%20T%20--%3E%7C%22%E6%98%AF%22%7C%20ACC%5B%22%E6%AD%A3%E5%B8%B8%E5%A4%84%E7%90%86%22%5D%0A%20%20T%20--%3E%7C%22%E5%90%A6%22%7C%20OLD%5B%22%E5%88%A4%E5%AE%9A%E4%B8%BA%E5%9B%9E%E7%BB%95%E5%89%8D%E7%9A%84%E6%97%A7%E6%AE%B5%22%5D%0A%20%20OLD%20--%3E%20DROP%5B%22%E4%B8%A2%E5%BC%83%E8%AF%A5%E6%AE%B5%EF%BC%8C%E8%BF%9E%E6%8E%A5%E4%B8%8D%E5%8F%97%E5%BD%B1%E5%93%8D%22%5D%0A%20%20G%5B%221%20Gb%2Fs%20%E4%B8%8B%2032%20%E4%BD%8D%E5%BA%8F%E5%8F%B7%E7%BA%A6%2034%20%E7%A7%92%E5%9B%9E%E7%BB%95%E4%B8%80%E5%9C%88%22%5D%20-.-%3E%7C%22%E8%BF%9F%E5%88%B0%E7%9A%84%E6%97%A7%E6%AE%B5%E6%B7%B7%E5%85%A5%22%7C%20OLD%0A"})]),fallback:e(()=>[...a[1]||(a[1]=[i(" Loading... ",-1)])]),_:1})),a[4]||(a[4]=s('<p>下一课<a href="/cs/mss-clamping">MSS 与钳制</a>。</p><h2 id="小结" tabindex="-1">小结 <a class="header-anchor" href="#小结" aria-label="Permalink to &quot;小结&quot;">​</a></h2><ul><li>窗口缩放表达 BDP；双方握手同意。</li><li>时间戳用于 RTT 与 PAWS。</li><li>中间剥选项造成假流控。</li><li>后课只引用本课钉死的对象，不从该领域总问题重开。</li><li>出处：RFC 7323。</li></ul>',3))])}const D=o(p,[["render",d]]);export{C as __pageData,D as default};
